import sys
lines = sys.stdin.read().splitlines()
out = []
if lines:
    parts = lines[0].split()
    n, m = int(parts[0]), int(parts[1])
    nums = [int(x) for x in lines[1].split()]
    tree = [float('inf')] * (4 * n)
    def build(node, l, r):
        if l == r:
            tree[node] = nums[l]; return
        mid = (l + r) // 2
        build(2*node, l, mid); build(2*node+1, mid+1, r)
        tree[node] = min(tree[2*node], tree[2*node+1])
    def update(node, l, r, idx, val):
        if l == r:
            tree[node] = val; return
        mid = (l + r) // 2
        if idx <= mid: update(2*node, l, mid, idx, val)
        else: update(2*node+1, mid+1, r, idx, val)
        tree[node] = min(tree[2*node], tree[2*node+1])
    def query(node, l, r, ql, qr):
        if ql <= l and r <= qr: return tree[node]
        if r < ql or l > qr: return float('inf')
        mid = (l + r) // 2
        return min(query(2*node, l, mid, ql, qr), query(2*node+1, mid+1, r, ql, qr))
    if n > 0:
        build(1, 0, n - 1)
        for line in lines[2:2+m]:
            cmd = line.split()
            if not cmd: continue
            if cmd[0] == 'UPDATE':
                idx, val = int(cmd[1]), int(cmd[2])
                update(1, 0, n - 1, idx, val)
            elif cmd[0] == 'QUERY':
                ql, qr = int(cmd[1]), int(cmd[2])
                out.append(str(query(1, 0, n - 1, ql, qr)))
print(' '.join(out))
